import{c as t,Q as n,j as r,m as o}from"./chunks/framework.BqPkuuVc.js";const u=JSON.parse('{"title":"Radio punches","description":"","frontmatter":{},"headers":[],"relativePath":"user/running-the-event/radio-punches.md","filePath":"user/running-the-event/radio-punches.md"}'),a={name:"user/running-the-event/radio-punches.md"};function s(i,e,h,d,c,g){return n(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="radio-punches" tabindex="-1">Radio punches <a class="header-anchor" href="#radio-punches" aria-label="Permalink to &quot;Radio punches&quot;">​</a></h1><p><strong>Audience:</strong> Timing operators monitoring the live feed of punches coming in from radio controls.</p><p>A <strong>radio punch</strong> is a punch that reaches Manager <em>live</em> as a competitor passes a control, rather than waiting for their card to be downloaded at the finish. The punch travels from a <strong>meshO Control</strong> unit to <strong>meshO Prime</strong>, over USB into Manager — or it can arrive over the network from an upstream system (see <a href="#forwarding-and-receiving-punches">Forwarding and receiving punches</a>). Either way it appears within seconds on the dashboard, the Leaderboard, Commentary, Tracking and Live View.</p><p>This page is about the <strong>Radio Punches</strong> view, where you watch the raw feed and act on it. For setting up the hardware, see <a href="./connecting-prime-and-radios">Connecting meshO Prime and radios</a>.</p><h2 id="the-radio-punches-view" tabindex="-1">The Radio Punches view <a class="header-anchor" href="#the-radio-punches-view" aria-label="Permalink to &quot;The Radio Punches view&quot;">​</a></h2><p>Open <strong>Radio Punches</strong> from the live section of the event navigation. (It only appears once <strong>meshO Prime</strong> or <strong>Accept SIRAP Punches</strong> is enabled for the event, and the event is running.) If neither source is on, the page explains how to enable one.</p><p>Each punch is a row, <strong>newest first</strong>:</p><table tabindex="0"><thead><tr><th>Column</th><th>What it shows</th></tr></thead><tbody><tr><td><strong>Card Number</strong></td><td>The card number that punched.</td></tr><tr><td><strong>Name</strong></td><td>The competitor that card belongs to. Click it to open their record.</td></tr><tr><td><strong>Control</strong></td><td>The control code that was punched.</td></tr><tr><td><strong>Punch Time</strong></td><td>The time of the punch.</td></tr></tbody></table><p>The list is always sorted by punch time (most recent at the top) and you can&#39;t re-sort it — it&#39;s a live feed. To find a particular punch, use the filters at the top: <strong>Search Card</strong>, <strong>Search Name</strong>, and the <strong>Control</strong> dropdown to show just one control.</p><h3 id="unknown-cards" tabindex="-1">Unknown cards <a class="header-anchor" href="#unknown-cards" aria-label="Permalink to &quot;Unknown cards&quot;">​</a></h3><p>If a card that punches isn&#39;t matched to a competitor in the event, its <strong>Name</strong> shows as <strong>Unknown</strong> — or, if the card is recognised in the <a href="./../reference/competitor-registry">Competitor Registry</a>, the person&#39;s name appears <strong>in brackets</strong>. Click it to <strong>add a competitor for that card</strong> on the spot, so their punches start counting.</p><h2 id="suppressing-a-stray-punch" tabindex="-1">Suppressing a stray punch <a class="header-anchor" href="#suppressing-a-stray-punch" aria-label="Permalink to &quot;Suppressing a stray punch&quot;">​</a></h2><p>A bad or duplicate punch (a unit double-reporting, someone testing a control) is handled on the <strong>competitor</strong>, not in this list. Open the competitor, go to their <strong>Radio Punches</strong> tab, and <strong>suppress</strong> the punch — it&#39;s kept but greyed out and struck through, so it no longer affects the result and you can see what you did. <strong>Reinstate</strong> it the same way if you change your mind. See <a href="./resolving-issues">Resolving issues on the day</a>.</p><p>Late and duplicate punches are otherwise handled automatically: punches are processed in time order per competitor, and a punch Manager already has is ignored rather than counted twice.</p><h2 id="recovering-missed-punches" tabindex="-1">Recovering missed punches <a class="header-anchor" href="#recovering-missed-punches" aria-label="Permalink to &quot;Recovering missed punches&quot;">​</a></h2><p>If Prime was connected for some time before the event was started, those punches will not have reached Manager — but they&#39;re still in Prime&#39;s memory. From the Radio Punches view&#39;s actions menu, choose <strong>Resend stored punches</strong>:</p><blockquote><p><em>meshO Prime will resend every punch that is still in its memory. Duplicate punches will be ignored.</em></p></blockquote><p>Prime replays its whole memory and Manager fills in anything it missed, skipping what it already has. (This is available while the event is in progress and Prime is the punch source.)</p><h2 id="forwarding-and-receiving-punches" tabindex="-1">Forwarding and receiving punches <a class="header-anchor" href="#forwarding-and-receiving-punches" aria-label="Permalink to &quot;Forwarding and receiving punches&quot;">​</a></h2><p>Manager can pass radio punches to and from other systems over the network:</p><ul><li><strong>Forwarding (outbound)</strong> — send every punch on to a downstream system as it arrives. Turn on <strong>Forward Radio Punches</strong> on the event&#39;s <strong>Radio Controls</strong> tab, and set the destination <strong>host</strong>, <strong>port</strong> and <strong>protocol</strong> (SIRAP or OE12) in <a href="./../reference/settings">Settings</a>. The dashboard&#39;s <strong>Radio Punch Forwarding</strong> card shows <strong>Active</strong> / <strong>Disabled</strong> with running <strong>Sent</strong> and <strong>Queued</strong> counts.</li><li><strong>Receiving (inbound, SIRAP)</strong> — accept punches from an upstream system. Turn on <strong>Accept SIRAP Punches</strong> for the event and set the listening <strong>port</strong> in Settings. The dashboard&#39;s <strong>SIRAP Punch Listening</strong> card shows <strong>Listening</strong> / <strong>Stopped</strong> and a <strong>Received</strong> count, which starts again from zero each time an event starts accepting punches — so it counts the event you are running, not everything since Manager was opened. Punches that arrive this way appear in the Radio Punches list just like Prime&#39;s.</li></ul><p>Forwarding and receiving are independent — you can do either, both, or neither.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./connecting-prime-and-radios">Connecting meshO Prime and radios</a> — the hardware behind the feed</li><li><a href="./../event-setup/controls-and-radio-controls">Controls and radio controls</a> — control codes and the Start/Finish/Check codes</li><li><a href="./tracking">Tracking</a> and <a href="./live-view">Live view</a> — the spatial view of the same data</li><li><a href="./station-memory">Station Memory</a> — recovering punches a control never sent</li></ul>',24)])])}const l=t(a,[["render",s]]);export{u as __pageData,l as default};
